WITH schema AS (
  SELECT '{
    "type": "object",
    "properties": {"id": {"type": "integer"}},
    "required": ["id"]
  }'::JSON AS definition
), events(row_num, payload) AS (
  VALUES
    (1, '{"id": 42}'::JSON),
    (2, '{"id": "oops"}'::JSON)
)
SELECT row_num, payload,
  COALESCE(
    TRY(json_schema_validate(definition, payload)), false
  ) AS valid
FROM events CROSS JOIN schema
ORDER BY row_num;
